import base64
import cv2
import numpy as np
TEMPLATES = {'images/end_results/1st_ru_2026.png': '', 'images/end_results/2nd_ru_2026.png': '', 'images/end_results/3rd_ru_2026.png': '', 'images/states/idle_disconnect_ru.png': '', 'images/states/login_failure_ru.png': '', 'images/states/respawn_ru.png': '', 'images/states/team_panel_ru.png': '', 'images/states/teams_remaining_ru.png': ''}

def image_for(path):
    key = str(path).replace("\\", "/")
    marker = key.rfind("images/")
    data = TEMPLATES.get(key[marker:]) if marker >= 0 else None
    return cv2.imdecode(np.frombuffer(base64.b64decode(data), np.uint8), cv2.IMREAD_COLOR) if data else None

# English HUD captured from the user-provided dataset, not a translated guess.
